# تعليق صوتي مشكول بأسلوب سرديّ لفيديو الدرس ١-٦ «القوى والجذور» — مجاني عبر edge-tts، مع معالجة صوتية لليوتيوب.
# pip install edge-tts mutagen imageio-ffmpeg
# SSL_CERT_FILE=/root/.ccr/ca-bundle.crt python3 gen_powers_voice.py [الصوت] [مجلد] [أرقام المشاهد…]
import asyncio, json, os, ssl, sys, subprocess, edge_tts, imageio_ffmpeg
from mutagen.mp3 import MP3
if os.environ.get('SSL_CERT_FILE'):  # خلف وكيلٍ بشهادةٍ خاصة
    edge_tts.communicate._SSL_CTX = ssl.create_default_context(cafile=os.environ['SSL_CERT_FILE'])
HERE = os.path.dirname(os.path.abspath(__file__))
VOICE = sys.argv[1] if len(sys.argv) > 1 else 'ar-SA-HamedNeural'
OUT = sys.argv[2] if len(sys.argv) > 2 else os.path.join(HERE, 'صوت')
ONLY = [int(x) for x in sys.argv[3:]]
RATE, PITCH = '-6%', '-2Hz'
LINES = [
 'أَهْلًا بِكُمْ يَا أَبْطَالَ الرِّيَاضِيَّاتِ! هَلْ تَسَاءَلْتُمْ يَوْمًا... كَيْفَ نَكْتُبُ عَمَلِيَّةَ ضَرْبٍ طَوِيلَةً بِطَرِيقَةٍ مُخْتَصَرَةٍ؟ هَذَا مَا سَنَكْتَشِفُهُ مَعًا الْيَوْمَ، فِي دَرْسِ: الْقُوَى وَالْجُذُورِ.',
 'لِنَبْدَأْ بِهَذَا الْمِثَالِ: خَمْسَةٌ، فِي خَمْسَةٍ، فِي خَمْسَةٍ. أَلَيْسَتْ طَوِيلَةً؟ نَخْتَصِرُهَا هَكَذَا: خَمْسَةٌ أُسُّ ثَلَاثَةٍ... وَنَاتِجُهَا مِئَةٌ وَخَمْسَةٌ وَعِشْرُونَ. الْعَدَدُ الْكَبِيرُ، خَمْسَةٌ، هُوَ الْأَسَاسُ: الْعَدَدُ الَّذِي نَضْرِبُهُ. وَالْعَدَدُ الصَّغِيرُ فِي الْأَعْلَى، ثَلَاثَةٌ، هُوَ الْأُسُّ: يُخْبِرُنَا كَمْ مَرَّةً نَكْتُبُ الْأَسَاسَ.',
 'انْظُرُوا إِلَى هَذَا الْمُرَبَّعِ: خَمْسَةُ صُفُوفٍ، فِي كُلِّ صَفٍّ خَمْسَةُ مُرَبَّعَاتٍ. إِذَنْ، خَمْسَةٌ تَرْبِيع تُسَاوِي خَمْسَةً وَعِشْرِينَ. وَالْآنَ نَبْنِي مُكَعَّبًا: خَمْسُ طَبَقَاتٍ، فِي كُلِّ طَبَقَةٍ خَمْسَةٌ وَعِشْرُونَ... وَالْمَجْمُوعُ؟ مِئَةٌ وَخَمْسَةٌ وَعِشْرُونَ. هَذَا هُوَ: خَمْسَةٌ تَكْعِيب.',
 'وَإِلَيْكُمْ حِيلَةً سَرِيعَةً مَعَ الْعَدَدِ عَشَرَةٍ: عَدَدُ الْأَصْفَارِ يُسَاوِي الْأُسَّ! عَشَرَةٌ أُسُّ ثَلَاثَةٍ؟ وَاحِدٌ، وَثَلَاثَةُ أَصْفَارٍ: أَلْفٌ. وَعَشَرَةٌ أُسُّ سِتَّةٍ؟ وَاحِدٌ، وَسِتَّةُ أَصْفَارٍ: مِلْيُونٌ كَامِلٌ!',
 'تَوَقَّفُوا لَحْظَةً! هُنَا يَقَعُ كَثِيرٌ مِنَ الطُّلَّابِ فِي خَطَأٍ شَائِعٍ. أَرْبَعَةٌ تَرْبِيع... لَيْسَتْ أَرْبَعَةً فِي اثْنَيْنِ! فَالْأُسُّ لَيْسَ عَدَدًا نَضْرِبُ فِيهِ. الصَّحِيحُ: أَرْبَعَةٌ فِي أَرْبَعَةٍ، وَالنَّاتِجُ: سِتَّةَ عَشَرَ.',
 'وَالْآنَ نَعْكِسُ الِاتِّجَاهَ. الْجَذْرُ التَّرْبِيعِيُّ هُوَ عَكْسُ التَّرْبِيعِ. خَمْسَةٌ تَرْبِيع تُسَاوِي خَمْسَةً وَعِشْرِينَ، وَسَالِبُ خَمْسَةٍ تَرْبِيع يُسَاوِي خَمْسَةً وَعِشْرِينَ أَيْضًا! لِذَلِكَ، لِلْعَدَدِ خَمْسَةٍ وَعِشْرِينَ جَذْرَانِ تَرْبِيعِيَّانِ: مُوجَبُ خَمْسَةٍ، وَسَالِبُ خَمْسَةٍ.',
 'وَمَاذَا عَنِ الْجَذْرِ التَّكْعِيبِيِّ؟ إِنَّهُ عَكْسُ التَّكْعِيبِ. خَمْسَةٌ تَكْعِيب تُسَاوِي مِئَةً وَخَمْسَةً وَعِشْرِينَ، إِذَنِ الْجَذْرُ التَّكْعِيبِيُّ لِمِئَةٍ وَخَمْسَةٍ وَعِشْرِينَ هُوَ خَمْسَةٌ. وَهُنَا جَذْرٌ وَاحِدٌ فَقَطْ... لِأَنَّ سَالِبَ خَمْسَةٍ تَكْعِيب يُعْطِينَا سَالِبَ مِئَةٍ وَخَمْسَةٍ وَعِشْرِينَ.',
 'ثَلَاثُ قَوَاعِدَ ذَهَبِيَّةٍ لَا تَنْسَوْهَا: أَوَّلًا، نُكْمِلُ الْعَمَلِيَّةَ دَاخِلَ الْجَذْرِ قَبْلَ أَيِّ شَيْءٍ. ثَانِيًا، التَّرْبِيعُ يُلْغِي الْجَذْرَ التَّرْبِيعِيَّ. ثَالِثًا، الْعَدَدُ الْمُرَبَّعُ لَا يَنْتَهِي إِلَّا بِصِفْرٍ، أَوْ وَاحِدٍ، أَوْ أَرْبَعَةٍ، أَوْ خَمْسَةٍ، أَوْ سِتَّةٍ، أَوْ تِسْعَةٍ.',
 'وَالْآنَ... جَاءَ دَوْرُكُمْ! احْفَظُوا الْأَعْدَادَ الْمُرَبَّعَةَ حَتَّى عِشْرِينَ تَرْبِيع، وَمُكَعَّبَاتِ الْأَعْدَادِ مِنْ وَاحِدٍ إِلَى عَشَرَةٍ، وَرَاجِعُوا وَرَقَةَ الْمُلَخَّصِ قَبْلَ الِاخْتِبَارِ. أَحْسَنْتُمْ... وَإِلَى اللِّقَاءِ فِي الدَّرْسِ الْقَادِمِ!',
]
# معالجة صوتية: إزالة الترددات المنخفضة، دفء خفيف، ضغط ناعم، ومستوى صوت يوتيوب (−١٤ LUFS)، ٤٨ كيلوهرتز
MASTER = ('highpass=f=70,equalizer=f=180:t=q:w=1:g=2,equalizer=f=3500:t=q:w=1.2:g=2.5,'
          'acompressor=threshold=-20dB:ratio=3:attack=5:release=120:makeup=2,'
          'loudnorm=I=-14:TP=-1.5:LRA=7,aresample=48000')
FF = imageio_ffmpeg.get_ffmpeg_exe()
async def main():
    os.makedirs(OUT, exist_ok=True); durs = []
    for i, t in enumerate(LINES, 1):
        if ONLY and i not in ONLY: continue
        raw, f = os.path.join(OUT, f'raw_{i:02d}.mp3'), os.path.join(OUT, f'powers_{i:02d}.mp3')
        await edge_tts.Communicate(t, VOICE, rate=RATE, pitch=PITCH).save(raw)
        subprocess.run([FF, '-y', '-loglevel', 'error', '-i', raw, '-af', MASTER, '-ac', '2', '-b:a', '192k', f], check=True)
        os.remove(raw); durs.append(round(MP3(f).info.length, 2))
    if not ONLY:
        json.dump({'voice': VOICE, 'durations': durs, 'lines': LINES}, open(os.path.join(OUT, 'durations.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print(VOICE, durs)
asyncio.run(main())
